-- ADMIN SETUP: run once in Supabase > SQL Editor. Safe to re-run.
-- BEFORE running: check your current MVP view with  select pg_get_viewdef('player_mvp_points');
-- and compare it with the replacement near the bottom of this file.

-- ===== staff + permission helpers (levels: mod < admin < owner) =====
create table if not exists staff(email text primary key, role text not null check (role in ('owner','admin','moderator')), created_at timestamptz default now());
create or replace function staff_role() returns text language sql stable security definer set search_path=public as
$$ select role from staff where lower(email)=lower(coalesce(auth.jwt()->>'email','')) limit 1 $$;
create or replace function has_level(lvl text) returns boolean language sql stable security definer set search_path=public as
$$ select case staff_role() when 'owner' then true when 'admin' then lvl in ('mod','admin') when 'moderator' then lvl='mod' else false end $$;
-- FIRST OWNER: change to the Google account you will sign in with
insert into staff values ('yualan480@gmail.com','owner') on conflict do nothing;

-- ===== tables =====
create table if not exists site_settings(key text primary key, value jsonb not null, updated_at timestamptz default now());
insert into site_settings values ('maintenance','false'),('maintenance_msg','"We are updating the site. Back soon!"'),('registration_enabled','true'),
 ('chat_enabled','true'),('chat_slow_seconds','0'),('chat_max_len','200'),('suggestions_enabled','true') on conflict do nothing;
create table if not exists player_status(name text primary key, display text, state text not null default 'ok' check (state in ('ok','muted','banned','suspended')),
 until timestamptz, chat_banned boolean not null default false, reason text, updated_at timestamptz default now());
create table if not exists announcements(id bigint generated always as identity primary key, title text not null, body text, kind text default 'info',
 pinned boolean default false, active boolean default true, starts_at timestamptz, ends_at timestamptz, created_at timestamptz default now());
create table if not exists games_config(id text primary key, title text, description text, icon text, category text, page text, enabled boolean default true,
 featured boolean default false, is_new boolean default false, is_popular boolean default false, sort_order int default 0);
insert into games_config(id,title,page,sort_order) values ('blockblast','Block Blast','blockblast.html',1),('tetris','Tetris','tetris.html',2),('game2048','2048','2048.html',3),
 ('snake','Snake','snake.html',4),('pacman','Pac-Man','pacman.html',5),('breakout','Block Breaker','breakout.html',6),('minesweeper','Minesweeper','minesweeper.html',7),
 ('flappy','Flappy Bird','flappy.html',8),('dino','Dino Run','dino.html',9),('blockout','Blockout','blockout.html',10),('getaway','Getaway Shootout','getaway.html',11),
 ('battleship','Battleship','battleship.html',12) on conflict do nothing;
create table if not exists suggestions(id bigint generated always as identity primary key, kind text default 'suggestion', message text not null,
 status text default 'pending', note text, created_at timestamptz default now());
create table if not exists mvp_adjustments(id bigint generated always as identity primary key, name text not null, delta int not null, reason text, created_at timestamptz default now());
create table if not exists admin_log(id bigint generated always as identity primary key, at timestamptz default now(), actor text, action text, target text, detail jsonb);
alter table chat_messages add column if not exists pinned boolean default false;
alter table scores add column if not exists id bigint generated by default as identity;

-- ===== audit log: every staff change is recorded by the database itself =====
create or replace function audit() returns trigger language plpgsql security definer set search_path=public as $$
begin
  if current_setting('app.bulk',true)='1' or auth.jwt()->>'email' is null then return null; end if;
  insert into admin_log(actor,action,target,detail) values (auth.jwt()->>'email',tg_op,tg_table_name,to_jsonb(case when tg_op='DELETE' then old else new end));
  return null;
end $$;
do $$ declare t text; begin
  foreach t in array array['site_settings','player_status','announcements','games_config','mvp_adjustments','staff'] loop
    execute format('drop trigger if exists trg_audit on %I; create trigger trg_audit after insert or update or delete on %I for each row execute function audit()',t,t); end loop;
  foreach t in array array['suggestions','scores','chat_messages'] loop
    execute format('drop trigger if exists trg_audit on %I; create trigger trg_audit after update or delete on %I for each row execute function audit()',t,t); end loop;
end $$;

-- ===== enforcement on the server (cannot be bypassed from the browser) =====
create or replace function setting(k text) returns jsonb language sql stable security definer set search_path=public as $$ select value from site_settings where key=k $$;
create or replace function guard() returns trigger language plpgsql security definer set search_path=public as $$
declare s player_status; n int;
begin
  select * into s from player_status where name=lower(new.name);
  if s.state in ('banned','suspended') and (s.until is null or s.until>now()) then raise exception 'Your account is restricted.'; end if;
  if coalesce(setting('maintenance')::text,'false')='true' then raise exception 'The site is under maintenance.'; end if;
  if coalesce(setting('registration_enabled')::text,'true')<>'true'
     and not exists(select 1 from scores where lower(name)=lower(new.name)) and not exists(select 1 from chat_messages where lower(name)=lower(new.name))
  then raise exception 'New sign-ups are closed right now.'; end if;
  if tg_table_name='chat_messages' then
    if coalesce(setting('chat_enabled')::text,'true')<>'true' then raise exception 'Chat is turned off right now.'; end if;
    if s.chat_banned or (s.state='muted' and (s.until is null or s.until>now())) then raise exception 'You are muted.'; end if;
    if length(new.message)>coalesce((setting('chat_max_len')#>>'{}')::int,200) then raise exception 'Message is too long.'; end if;
    n:=coalesce((setting('chat_slow_seconds')#>>'{}')::int,0);
    if n>0 and exists(select 1 from chat_messages where lower(name)=lower(new.name) and created_at>now()-make_interval(secs=>n)) then raise exception 'Slow mode is on. Wait % seconds.',n; end if;
  else
    if exists(select 1 from games_config where id=new.game and not enabled) then raise exception 'That game is turned off.'; end if;
  end if;
  return new;
end $$;
drop trigger if exists trg_guard on chat_messages; create trigger trg_guard before insert on chat_messages for each row execute function guard();
drop trigger if exists trg_guard on scores;        create trigger trg_guard before insert on scores        for each row execute function guard();

-- ===== row level security =====
do $$ declare t text; begin
  foreach t in array array['staff','site_settings','player_status','announcements','games_config','suggestions','mvp_adjustments','admin_log'] loop
    execute format('alter table %I enable row level security',t); end loop; end $$;
drop policy if exists p_staff on staff;              create policy p_staff on staff for all using (has_level('owner')) with check (has_level('owner'));
drop policy if exists p_staff_r on staff;            create policy p_staff_r on staff for select using (has_level('mod'));
drop policy if exists p_set_r on site_settings;      create policy p_set_r on site_settings for select using (true);
drop policy if exists p_set_w on site_settings;      create policy p_set_w on site_settings for all using (has_level('owner') or (key like 'chat%' and has_level('admin'))) with check (has_level('owner') or (key like 'chat%' and has_level('admin')));
drop policy if exists p_ps_r on player_status;       create policy p_ps_r on player_status for select using (has_level('mod'));
drop policy if exists p_ps_w on player_status;       create policy p_ps_w on player_status for all using (has_level('admin') or (has_level('mod') and state in ('ok','muted'))) with check (has_level('admin') or (has_level('mod') and state in ('ok','muted')));
drop policy if exists p_an_r on announcements;       create policy p_an_r on announcements for select using (active and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>now()));
drop policy if exists p_an_w on announcements;       create policy p_an_w on announcements for all using (has_level('admin')) with check (has_level('admin'));
drop policy if exists p_gc_r on games_config;        create policy p_gc_r on games_config for select using (true);
drop policy if exists p_gc_w on games_config;        create policy p_gc_w on games_config for all using (has_level('admin')) with check (has_level('admin'));
drop policy if exists p_su_i on suggestions;         create policy p_su_i on suggestions for insert to anon, authenticated with check (length(message) between 1 and 500 and coalesce(setting('suggestions_enabled')::text,'true')='true');
drop policy if exists p_su_a on suggestions;         create policy p_su_a on suggestions for all using (has_level('admin')) with check (has_level('admin'));
drop policy if exists p_mv on mvp_adjustments;       create policy p_mv on mvp_adjustments for all using (has_level('admin')) with check (has_level('admin'));
drop policy if exists p_lg on admin_log;             create policy p_lg on admin_log for select using (has_level('admin'));
drop policy if exists p_cm_d on chat_messages;       create policy p_cm_d on chat_messages for delete using (has_level('mod'));
drop policy if exists p_cm_u on chat_messages;       create policy p_cm_u on chat_messages for update using (has_level('mod')) with check (has_level('mod'));
drop policy if exists p_sc_d on scores;              create policy p_sc_d on scores for delete using (has_level('admin'));
grant select on site_settings, announcements, games_config to anon, authenticated;
grant insert on suggestions to anon, authenticated;
grant select,insert,update,delete on staff, site_settings, player_status, announcements, games_config, suggestions, mvp_adjustments to authenticated;
grant select on admin_log to authenticated;
grant update, delete on chat_messages, scores to authenticated;

-- ===== admin functions =====
create or replace function admin_dashboard() returns jsonb language sql stable security definer set search_path=public as $$
 select case when has_level('mod') then jsonb_build_object(
  'players',(select count(distinct lower(name)) from (select name from scores union all select name from chat_messages) x),
  'accounts',(select count(*) from profiles),'scores',(select count(*) from scores),
  'msgs24',(select count(*) from chat_messages where created_at>now()-interval '24 hours'),
  'pending',(select count(*) from suggestions where status in ('pending','open')),
  'restricted',(select count(*) from player_status where state<>'ok' or chat_banned),
  'log',(select coalesce(jsonb_agg(l),'[]') from (select at,actor,action,target from admin_log order by id desc limit 10) l)) end $$;
create or replace function admin_players(q text default '') returns table(name text, avatar text, created timestamptz, last_seen timestamptz, scores numeric, msgs numeric, state text, until timestamptz, chat_banned boolean)
language sql stable security definer set search_path=public as $$
 with n as (select lower(s.name) k, max(s.name) nm, min(created_at) f, max(created_at) l, count(*) c, 0 m from scores s group by 1
            union all select lower(c.name), max(c.name), min(created_at), max(created_at), 0, count(*) from chat_messages c group by 1),
 a as (select k, max(nm) nm, min(f) f, max(l) l, sum(c) c, sum(m) m from n group by k)
 select a.nm,
  (select case when av like 'data:%' then 'photo' else av end from (select avatar av from scores where lower(scores.name)=a.k order by created_at desc limit 1) z),
  (select min(u.created_at) from profiles pr join auth.users u on u.id=pr.user_id where lower(pr.data->'keys'->'player-name'->>'v')=a.k),
  a.l, a.c, a.m, coalesce(p.state,'ok'), p.until, coalesce(p.chat_banned,false)
 from a left join player_status p on p.name=a.k
 where has_level('mod') and a.k like '%'||lower(replace(q,'%',''))||'%' order by a.l desc limit 100 $$;
create or replace function admin_clear_chat() returns void language plpgsql security definer set search_path=public as $$
begin if not has_level('admin') then raise exception 'Not allowed'; end if;
 perform set_config('app.bulk','1',true); delete from chat_messages where true;
 insert into admin_log(actor,action,target) values (auth.jwt()->>'email','CLEAR_CHAT','chat_messages'); end $$;
create or replace function admin_reset_scores(g text) returns void language plpgsql security definer set search_path=public as $$
begin
 if g is null and not has_level('owner') then raise exception 'Only the owner can reset every leaderboard'; end if;
 if g is not null and not has_level('admin') then raise exception 'Not allowed'; end if;
 perform set_config('app.bulk','1',true); delete from scores where g is null or game=g;
 insert into admin_log(actor,action,target) values (auth.jwt()->>'email','RESET_SCORES',coalesce(g,'ALL GAMES')); end $$;
revoke all on function admin_dashboard(), admin_players(text), admin_clear_chat(), admin_reset_scores(text) from public;
grant execute on function admin_dashboard(), admin_players(text), admin_clear_chat(), admin_reset_scores(text), staff_role() to authenticated;

-- ===== MVP view: your existing rules + banned players excluded + admin adjustments =====
create or replace view public.player_mvp_points as
with best as (
  select s.game, lower(btrim(s.name)) as k, max(s.score) as score, (array_agg(s.name order by s.created_at desc))[1] as name
  from scores s
  where s.game = any (array['blockblast','tetris','game2048','snake','pacman','breakout','minesweeper','flappy','dino','blockout'])
    and not exists (select 1 from player_status p where p.name = lower(btrim(s.name)) and p.state in ('banned','suspended') and (p.until is null or p.until > now()))
  group by s.game, lower(btrim(s.name))
), ranked as (select b.game, b.k, b.score, b.name, rank() over (partition by b.game order by b.score desc) as place from best b),
pts as (select r.game, r.k, r.score, r.name, r.place, case when r.place <= 10 then 105 - 5 * r.place else 0::bigint end as points from ranked r),
base as (select k, (array_agg(name order by points desc, score desc))[1] as name, sum(points)::integer as total, (count(*) filter (where points > 0))::integer as games from pts group by k),
adj as (select lower(btrim(name)) as k, max(name) as name, sum(delta)::integer as d from mvp_adjustments group by 1)
select coalesce(b.k, a.k) as key, coalesce(b.name, a.name) as name, (coalesce(b.total,0)+coalesce(a.d,0))::integer as total, coalesce(b.games,0)::integer as games
from base b full join adj a on a.k = b.k;
grant select on public.player_mvp_points to anon, authenticated;
